    /**
     * Send one notification event into the runtime ingress path.
     */
    fun notifyNotificationEvent(
        event: RuntimeHostNotificationEvent,
    ) {
        val sequence = nextSequence
        nextSequence += 1L

        val bridgedEvent = event.copy(
            sequence = sequence,
            timestampNs = timestampNs(),
        )
        val status = runtimeApi.notifyNotificationEvent(
            sessionHandle = sessionHandle,
            event = bridgedEvent,
        )
        validateRuntimeIngressStatus(
            status,
            operation = "notification event",
        )
    }

